//! Every request and response body of `openapi.yaml` and `sync-openapi.yaml` round-trips through
//! its ov-protocol type, and every operation is built by a named builder (or excluded with a
//! reason). `openapi/samples.json` is generated by `cargo xtask openapi` from `vectors/openapi/`;
//! a key it has that isn't listed here fails, so a new endpoint fails CI until it is typed.

use std::collections::BTreeMap;

use ov_protocol::discovery::OpenVireoConfiguration;
use ov_protocol::types::*;
use serde::de::DeserializeOwned;
use serde::Serialize;
use serde_json::Value;

type Check = fn(&Value) -> Result<(), String>;

/// Deserialises the sample as `T`, serialises it back and requires the same JSON.
fn rt<T: DeserializeOwned + Serialize>(sample: &Value) -> Result<(), String> {
    let typed: T = serde_json::from_value(sample.clone()).map_err(|e| format!("deserialise: {e}"))?;
    let back = serde_json::to_value(&typed).map_err(|e| format!("serialise: {e}"))?;
    if &back == sample {
        Ok(())
    } else {
        Err(format!("round trip changed the JSON:\n  sample: {sample}\n  back:   {back}"))
    }
}

