/// Keys no client uses, with the reason.
const EXCLUDED: &[(&str, &str)] = &[
    ("sync POST /internal/notify op", "auth server → sync server only (SPEC §11)"),
    ("sync POST /internal/notify request", "auth server → sync server only (SPEC §11)"),
    ("sync DELETE /internal/vaults/{vault} op", "auth server → sync server only (SPEC §18)"),
];

fn samples() -> BTreeMap<String, Vec<Value>> {
    let text = include_str!("openapi/samples.json");
    serde_json::from_str(text).expect("samples.json is JSON; regenerate it with `cargo xtask openapi`")
}

#[test]
fn every_contract_key_is_typed_or_excluded() {
    let samples = samples();
    let bodies: BTreeMap<&str, Check> = bodies().into_iter().collect();
    let known =
        |k: &str| bodies.contains_key(k) || OPS.iter().any(|(o, _)| *o == k) || EXCLUDED.iter().any(|(e, _)| *e == k);
    let untyped: Vec<&String> = samples.keys().filter(|k| !known(k)).collect();
    assert!(
        untyped.is_empty(),
        "contract keys with no ov-protocol type or builder (type them, or exclude them with a reason): {untyped:#?}"
    );
    let listed = bodies.keys().copied().chain(OPS.iter().map(|(k, _)| *k)).chain(EXCLUDED.iter().map(|(k, _)| *k));
    let stale: Vec<&str> = listed.filter(|k| !samples.contains_key(*k)).collect();
    assert!(stale.is_empty(), "listed keys that aren't in the contract any more: {stale:#?}");
}

#[test]
fn every_sample_round_trips() {
    let samples = samples();
    let mut failures = Vec::new();
    let mut checked = 0;
    for (key, check) in bodies() {
        for (i, sample) in samples.get(key).into_iter().flatten().enumerate() {
            checked += 1;
            if let Err(e) = check(sample) {
                failures.push(format!("{key} [variant {i}]: {e}"));
            }
        }
    }
    assert!(failures.is_empty(), "{} failures:\n{}", failures.len(), failures.join("\n"));
    println!("{checked} samples round-tripped");
}

/// The contract's only `example` values, checked by name so a lost example is noticed.
#[test]
fn contract_examples_are_in_the_samples() {
    let s = samples();
    assert_eq!(s["auth POST /auth/refresh 200"][0]["expires_in"], 600);
    assert_eq!(s["auth GET /orgs/{org}/audit 200"][0]["events"][0]["action"], "vault.access.grant");
}

/// The discovery document isn't in openapi.yaml; SPEC §10's example stands in for it.
#[test]
fn discovery_example_round_trips() {
    let spec = serde_json::json!({"issuer":"https://accounts.openvireo.com","api":"https://accounts.openvireo.com/api/v1",
        "sync":"https://sync.openvireo.com/api/v1","jwks_uri":"https://accounts.openvireo.com/.well-known/jwks.json",
        "opaque":{"lib":"libopaque","version":"1.0.1-6e9ac92","context":"ov-opaque-v1","ids":"accounts.openvireo.com"},
        "kdf_min":{"m":19456,"t":2},"web":"https://app.openvireo.com"});
    rt::<OpenVireoConfiguration>(&spec).unwrap();
}

/// The harness itself: a field the type drops, a wrong type, or a missing required field fails.
#[test]
fn round_trip_catches_drift() {
    let kdf = serde_json::json!({"alg": "argon2id", "salt": "AA", "m": 1, "t": 1, "p": 1});
    rt::<Kdf>(&kdf).unwrap();
    let mut extra = kdf.clone();
    extra["new_field"] = 1.into();
    assert!(rt::<Kdf>(&extra).unwrap_err().contains("round trip changed"));
    let mut wrong = kdf.clone();
    wrong["m"] = "1".into();
    assert!(rt::<Kdf>(&wrong).unwrap_err().starts_with("deserialise"));
    let mut missing = kdf;
    missing.as_object_mut().unwrap().remove("salt");
    assert!(rt::<Kdf>(&missing).is_err());
}
